    "title": "专访丨全球发展倡议推动将发展置于国际议程中心位置——访巴基斯坦常驻联合国日内瓦办事处代表安德拉比",
    "link": "http://www.news.cn/20261011/996b72042be74b01906ef33001355cf0/c.html",
    "pub_date": "2026-10-11 08:46:43",
    "author": "王露,马汝轩",
    "description": "新华社日内瓦10月11日电 专访｜全球发展倡议推动将发展置于国际议程中心位置——访巴基斯坦常驻联合国日内瓦办事处代表安德拉比 新华社记者王露 马汝轩 巴基斯坦常驻联合国日内瓦办事处代表安德拉比日前接受新华社记者专访时表示，全球发展倡议提出5年来，在促进多边主义、推动南南合作方面发挥了关键作用，推动将发展置于国际议程中心位置。 安德拉比说，全球发展倡议提出的时机极为重要。经济发展议题在全球议程中一度被边缘化，如今它被重新置于国际议程的中心…",
    "content": "新华社日内瓦10月11日电 专访｜全球发展倡议推动将发展置于国际议程中心位置——访巴基斯坦常驻联合国日内瓦办事处代表安德拉比 新华社记者王露 马汝轩 巴基斯坦常驻联合国日内瓦办事处代表安德拉比日前接受新华社记者专访时表示，全球发展倡议提出5年来，在促进多边主义、推动南南合作方面发挥了关键作用，推动将发展置于国际议程中心位置。 安德拉比说，全球发展倡议提出的时机极为重要。经济发展议题在全球议程中一度被边缘化，如今它被重新置于国际议程的中心位置，这是全球发展倡议的重要贡献。过去5年里，该倡议下1800多个“小而美”合作…"
