    "description": "2026年10月11日 金秋访古城，西安觅诗韵。 陕西西安市长安区，潏河畔的桃溪堡村是诗中故地。在这里，唐代诗人崔护曾写下“去年今日此门中，人面桃花相映红”的名句。千余年后，游人纷纷前来。 手机屏幕里，微短剧《人面桃花》“红”在云端。西安通过影像“重译”唐诗，古老故事融入时代潮流。 一座长安城，半部《全唐诗》。如今的古城西安，正成为一座“活态唐诗博物馆”。 2023年5月，习近平总书记在听取陕西省委和省政府工作汇报时，要求陕西“用好自身…",
