    "description": "2026年10月11日 新华社北京10月10日电 （记者郑直）由中国残联组建的爱知·名古屋亚残运会中国体育代表团10日在北京成立，这是我国参加境外亚残运会运动员规模最大的一届。 中国体育代表团总计500人，其中运动员312人（含男运动员146人、女运动员166人），来自全国25个省（区、市），涵盖13个民族，平均年龄约为28.8岁，年龄最大者50岁，年龄最小者16岁；所有运动员均为业余选手，来自工人、学生、职员、自由职业者等不同群体。中…",
