    "title": "02版 - 食品安全法大幅修订回应哪些关切",
    "link": "http://paper.people.com.cn/rmrb/pc/content/202610/11/content_30184936.html",
    "pub_date": "2026-10-11 08:26:03",
    "author": "",
    "description": "2026年10月11日 10月10日，市场监管总局就《中华人民共和国食品安全法（修订草案征求意见稿）》（以下简称《征求意见稿》）面向社会公开征求意见。这是食品安全法自2009年颁布施行、2015年较大幅度修订之后的一次大规模系统性修订。 首次将直播带货等新业态纳入调整范围 校园食品安全供餐体量大、用餐群体敏感、社会关注程度高。《征求意见稿》针对“学校食品安全”增设专节，确立校长（园长）负责制，建立中小学、幼儿园集中用餐陪餐制度。 “现行…",
    "content": "2026年10月11日 10月10日，市场监管总局就《中华人民共和国食品安全法（修订草案征求意见稿）》（以下简称《征求意见稿》）面向社会公开征求意见。这是食品安全法自2009年颁布施行、2015年较大幅度修订之后的一次大规模系统性修订。 首次将直播带货等新业态纳入调整范围 校园食品安全供餐体量大、用餐群体敏感、社会关注程度高。《征求意见稿》针对“学校食品安全”增设专节，确立校长（园长）负责制，建立中小学、幼儿园集中用餐陪餐制度。 “现行食品安全法对校园食品安全的规定相对原则，仅靠部门规章或者规范性文件权威性不够、刚…"
