    "description": "2026年10月11日 本报北京10月10日电 （记者刘志强）国家发展改革委国家信息中心发布的高频数据显示：三季度，存量政策、增量政策协同发力、集成显效，推动经济保持稳中有进、稳中向优态势，增长动能持续积蓄。 消费方面，线下消费大数据显示，三季度各类消费支付金额同比增长2.6%，增速较二季度提高0.7个百分点，其中商品消费增长4.5%。9月线下支付金额同比增长3.1%，增速较8月提高0.5个百分点，连续3个月上行。反映中小型商户活力的“…",
