    "description": "2026年10月11日 淡化、篡改甚至粉饰历史，只会让后人失去警惕，增加战争悲剧重演的风险 今年，美国加利福尼亚州旧金山国家公墓举行了纪念“巴丹死亡行军”84周年活动。“巴丹死亡行军”与南京大屠杀、缅泰死亡铁路并称为“远东三大战争暴行”。铭记这段历史，是为了让世人真正汲取战争的教训。尤其对当代青年学生而言，只有认清战争的残酷现实，理解和平的来之不易，才能成长为心怀责任的未来社会中坚。历史不会随风消散，也不应被篡改，否则悲剧就可能以新的形…",
    "content": "2026年10月11日 淡化、篡改甚至粉饰历史，只会让后人失去警惕，增加战争悲剧重演的风险 今年，美国加利福尼亚州旧金山国家公墓举行了纪念“巴丹死亡行军”84周年活动。“巴丹死亡行军”与南京大屠杀、缅泰死亡铁路并称为“远东三大战争暴行”。铭记这段历史，是为了让世人真正汲取战争的教训。尤其对当代青年学生而言，只有认清战争的残酷现实，理解和平的来之不易，才能成长为心怀责任的未来社会中坚。历史不会随风消散，也不应被篡改，否则悲剧就可能以新的形式重演。 我从小在菲律宾长大，父亲讲述的战争故事，在年幼的我听来就像西部牛仔故事…"
