    "content": "2026年10月11日 本报长春10月10日电&nbsp;&nbsp;（记者蒋雪鸿、尹婕）10日，由中央宣传部会同国家林草局等部门开展的“探访东北虎豹国家公园”集中采访在吉林长春启动。 本次集中采访涉及两条采访线路，将组织媒体记者深入吉林桦甸市、珲春市，黑龙江东宁市、海林市等地调研采访，聚焦国家公园建设对促进东北虎、东北豹野生种群及栖息地保护和森林生态系统保护等的积极成效，生动展现国家公园内自然景观、地质遗迹和文化遗产资源以及一般控制区的发展情况。 采访过程中和结束后，各媒体将在重要版面、时段和所属网站、新媒体平台…"
