    "description": "2026年10月11日 没有双臂，生活该怎么过？ 4岁时的一场意外，让我永远失去了双臂。我至今记得，小时候第一次用脚趾夹地上的筷子，夹一次，掉一次。脚趾磨得发红、破皮，结了痂，又被磨破……那时候，我常常想，为什么命运要给我设下这么难的关卡？ 后来，我慢慢想通，既然不能选择境遇，何不试着学会坚强？ 16岁，我入选江西省残疾人游泳队，开启了7年的赛场逐梦之路。平时，我付出数倍于别人的努力，日均训练游程超万米，别人用手触壁转身，我就用额头，磕…",
    "content": "2026年10月11日 没有双臂，生活该怎么过？ 4岁时的一场意外，让我永远失去了双臂。我至今记得，小时候第一次用脚趾夹地上的筷子，夹一次，掉一次。脚趾磨得发红、破皮，结了痂，又被磨破……那时候，我常常想，为什么命运要给我设下这么难的关卡？ 后来，我慢慢想通，既然不能选择境遇，何不试着学会坚强？ 16岁，我入选江西省残疾人游泳队，开启了7年的赛场逐梦之路。平时，我付出数倍于别人的努力，日均训练游程超万米，别人用手触壁转身，我就用额头，磕碰淤青是家常便饭。靠着日复一日的坚持，我在国家级、省级残疾人赛事中斩获13枚奖牌…"
