    "description": "2026年10月11日 当AI（人工智能）会创作了，搞创作的人会被取代吗？ 看似简单的发问，却足够引人深思。笔者年初在浙江金华横店调研微短剧时，曾有常驻片场的群众演员发问，AI会彻底替代真人拍摄吗？当技术浪潮奔涌而至，这样的疑问，萦绕在内容从业者的心头。 以微短剧为例，看一组最新数据：今年前8个月上线微短剧43万部，是去年全年的13倍，其中AI剧占比超九成。但是，AIGC（人工智能生成内容）在拓展想象空间的同时，也沉淀了大量的AI垃圾。…",
    "content": "2026年10月11日 当AI（人工智能）会创作了，搞创作的人会被取代吗？ 看似简单的发问，却足够引人深思。笔者年初在浙江金华横店调研微短剧时，曾有常驻片场的群众演员发问，AI会彻底替代真人拍摄吗？当技术浪潮奔涌而至，这样的疑问，萦绕在内容从业者的心头。 以微短剧为例，看一组最新数据：今年前8个月上线微短剧43万部，是去年全年的13倍，其中AI剧占比超九成。但是，AIGC（人工智能生成内容）在拓展想象空间的同时，也沉淀了大量的AI垃圾。粗制滥造、套路复制甚至洗稿抄袭的现象屡见不鲜。 微短剧面临的问题，也反映了整个内…"
