    "author": "",
    "description": "2026年10月11日 秋山叠翠，林海幽深。“早就听说这里有一条原生态的红军小道，今天特意带着孩子来走一走。”来自江西吉安的游客刘女士，牵着孩子的手，站在江西赣州于都县祁禄山镇金沙村红军长征小道的入口处，目光望向密林深处。 金沙村深藏于赣南群山之间，一条全长19.34公里的山间古道穿行在林海之间。1934年10月，中央红军渡过于都河后，多支部队从此秘密向西行军，突破国民党军第一道封锁线。小道沿途分布着思源井、红五军团总军医处旧址、阻击战…",
    "content": "2026年10月11日 秋山叠翠，林海幽深。“早就听说这里有一条原生态的红军小道，今天特意带着孩子来走一走。”来自江西吉安的游客刘女士，牵着孩子的手，站在江西赣州于都县祁禄山镇金沙村红军长征小道的入口处，目光望向密林深处。 金沙村深藏于赣南群山之间，一条全长19.34公里的山间古道穿行在林海之间。1934年10月，中央红军渡过于都河后，多支部队从此秘密向西行军，突破国民党军第一道封锁线。小道沿途分布着思源井、红五军团总军医处旧址、阻击战场遗址等，留存着烽火岁月的印记。 “大家脚下踩的石板，是当年红军夜行军走过的路。…"
