    "description": "10月11日凌晨，沙特民航总局发布公告确认，10日下午利雅得哈立德国王国际机场遭袭事件已造成12人死309人伤，死伤者包括多国公民(目前尚无中国公民伤亡报告)。沙官方报告达曼机场等地也于10日夜遭袭。利雅得哈立德国王国际机场机场仍暂停运营，全国多地机场出现大面积异常。",
    "content": "10月11日凌晨，沙特民航总局发布公告确认，10日下午利雅得哈立德国王国际机场遭袭事件已造成12人死309人伤，死伤者包括多国公民(目前尚无中国公民伤亡报告)。沙官方报告达曼机场等地也于10日夜遭袭。利雅得哈立德国王国际机场机场仍暂停运营，全国多地机场出现大面积异常。"
