    "content": "新华社利雅得10月11日电（记者罗晨 王海洲）沙特阿拉伯民航总局11日凌晨发表声明说，位于首都利雅得的哈立德国王国际机场10日遭袭击，已造成12人死亡、309人受伤。 声明说，死者包括4名沙特人、2名孟加拉国人，其余6人分别来自美国、埃及、约旦、叙利亚、巴勒斯坦和苏丹。 声明还说，伤者正在当地多家医院接受治疗，部分伤者伤势严重。袭击造成的财产损失情况仍在评估中。 沙特民航总局10日发表声明说，哈立德国王国际机场当天下午遭到袭击，机场已暂停运营。沙特民航总局正与有关部门协调，待完成损失评估并确认设施安全后再恢复机场运…"
