    "pub_date": "2026-10-11 06:35:20",
    "author": "",
    "description": "10月10日，市场监管总局就《中华人民共和国食品安全法(修订草案征求意见稿)》(以下简称《征求意见稿》)面向社会公开征求意见。这是食品安全法自2009年颁布施行、2015年较大幅度修订之后的一次大规模系统性修订。",
    "content": "10月10日，市场监管总局就《中华人民共和国食品安全法(修订草案征求意见稿)》(以下简称《征求意见稿》)面向社会公开征求意见。这是食品安全法自2009年颁布施行、2015年较大幅度修订之后的一次大规模系统性修订。"
