    "content": "新华社巴拿马城10月10日电（记者许咏政 李佳旭）巴拿马政府10日宣布进入紧急状态以应对强震，协调救灾和援助工作。 巴拿马总统府部长奥里利亚克当天在总统府举行的新闻发布会上说，政府已宣布进入紧急状态，要求各部门和公共机构随时待命，调配必要资源，为受灾民众提供援助。 奥里利亚克说，巴总统穆利诺已指示成立专门委员会，负责协调救灾行动、统筹援助资源等。政府已在首都巴拿马城设立救灾物资收集点，各省政府也将接收社会捐赠物资。 巴拿马当地时间9日12时56分发生7.5级地震，震中位于该国洛斯桑托斯省托诺西西北约39公里处。地震…"
