    "description": "新华社伦敦10月10日电（记者赵家淞）英国南约克郡警方10日证实，一名男子当天在该地区一座野生动物园遭老虎袭击，因伤势严重当场死亡。 警方说，当天下午接到的报告称，在位于唐卡斯特市郊区的约克郡野生动物园内，一名男子进入老虎活动区域后遭到老虎袭击。急救人员赶到现场施救，但该男子最终不治身亡。 警方还说，涉事老虎事发后仍留在园区内，未对公众构成其他威胁。动物园随后组织游客撤离，警方正在调查事件具体经过。 约克郡野生动物园发表声明说，正与有关…",
    "content": "新华社伦敦10月10日电（记者赵家淞）英国南约克郡警方10日证实，一名男子当天在该地区一座野生动物园遭老虎袭击，因伤势严重当场死亡。 警方说，当天下午接到的报告称，在位于唐卡斯特市郊区的约克郡野生动物园内，一名男子进入老虎活动区域后遭到老虎袭击。急救人员赶到现场施救，但该男子最终不治身亡。 警方还说，涉事老虎事发后仍留在园区内，未对公众构成其他威胁。动物园随后组织游客撤离，警方正在调查事件具体经过。 约克郡野生动物园发表声明说，正与有关部门合作调查事件。动物园当天关闭，并将于11日继续闭园。 根据约克郡野生动物园官…"
