    "content": "内蒙古自治区是中国共产党领导下成立的第一个省级民族自治区。2023年6月，习近平总书记在内蒙古考察时指出，铸牢中华民族共同体意识是新时代党的民族工作的主线，也是民族地区各项工作的主线。 石榴花开耀北疆。内蒙古深入贯彻落实习近平总书记关于加强和改进民族工作的重要思想，紧紧围绕推进高质量发展这个首要任务，以铸牢中华民族共同体意识为主线，积极融入和服务构建新发展格局，促进各民族共同团结奋斗、共同繁荣发展。 近日，新华社记者随“铸牢共同体 中华一家亲”主题宣传活动，来到内蒙古采访，真实感受民族团结一家亲的温暖。在市井街巷，…"
