    "description": "新华社纽约10月10日电 据美国媒体10日报道，美国宾夕法尼亚州伊利市9日发生大规模枪击事件，造成包括枪手在内的至少9人死亡。 美国哥伦比亚广播公司10日报道说，有目击者称看到一名男子在伊利市佩里街附近朝人群开枪，随后进入一处住宅。警方于当地时间9日17时左右抵达案发现场。报道称，在该住宅附近街道上发现两名死者遗体，在该住宅内发现包括枪手在内7名死者的遗体，枪手疑似自杀。 报道说，警方尚未公布枪手身份和作案动机。",
