    "description": "新华社法兰克福10月10日电（记者褚怡 单玮怡）日前，中国发展出版社在2026年德国法兰克福书展期间举办《中国发展报告2026》《全球发展报告2026（主要观点）》中英文版海外发布式暨智库对话会。中德两国出版、文化界50余人出席活动。 国务院发展研究中心副主任杨正位在视频致辞中表示，《中国发展报告2026》全面记录了过去一年中国在理论、制度和实践层面取得的发展成果。《全球发展报告2026》则以“合作增强全球发展的稳定性”为主题，分析变乱…",
    "content": "新华社法兰克福10月10日电（记者褚怡 单玮怡）日前，中国发展出版社在2026年德国法兰克福书展期间举办《中国发展报告2026》《全球发展报告2026（主要观点）》中英文版海外发布式暨智库对话会。中德两国出版、文化界50余人出席活动。 国务院发展研究中心副主任杨正位在视频致辞中表示，《中国发展报告2026》全面记录了过去一年中国在理论、制度和实践层面取得的发展成果。《全球发展报告2026》则以“合作增强全球发展的稳定性”为主题，分析变乱交织背景下全球发展的总体形势，阐释合作增进全球发展稳定性的作用，提出深化国际合作…"
