    "description": "中新社北京10月10日电 (记者 国璇)10日在北京进行的2026中国网球公开赛女子单打半决赛中，中国选手郑钦文以7:5、6:2力克赛会13号种子、比利时名将梅尔滕斯，职业生涯首次晋级中网女单决赛。郑钦文不仅是中网历史上首位持外卡打入女单决赛的球员，也是首位跻身中网单打决赛的本土球员。",
    "content": "中新社北京10月10日电 (记者 国璇)10日在北京进行的2026中国网球公开赛女子单打半决赛中，中国选手郑钦文以7:5、6:2力克赛会13号种子、比利时名将梅尔滕斯，职业生涯首次晋级中网女单决赛。郑钦文不仅是中网历史上首位持外卡打入女单决赛的球员，也是首位跻身中网单打决赛的本土球员。"
