    "description": "新华社北京10月10日电（记者王春涛）国防部新闻发言人陈曦10日就近期涉军问题发布消息并答记者问。 愿同美方一道落实好两国元首重要共识 有记者问，前不久，国家主席习近平对美国进行国事访问期间表示，两国军队要保持常态化对话，完善危机沟通和预防机制。请介绍中美两军下步交往有关考虑。 “元首外交是中美关系的定盘星，对两军关系发展起着把舵定向的引领性作用。”陈曦表示，中国军队愿同美方一道，落实好两国元首达成的重要共识，加强沟通对话，拓展交流合作…",
    "content": "新华社北京10月10日电（记者王春涛）国防部新闻发言人陈曦10日就近期涉军问题发布消息并答记者问。 愿同美方一道落实好两国元首重要共识 有记者问，前不久，国家主席习近平对美国进行国事访问期间表示，两国军队要保持常态化对话，完善危机沟通和预防机制。请介绍中美两军下步交往有关考虑。 “元首外交是中美关系的定盘星，对两军关系发展起着把舵定向的引领性作用。”陈曦表示，中国军队愿同美方一道，落实好两国元首达成的重要共识，加强沟通对话，拓展交流合作，妥善管控分歧，推动两军关系稳定、健康、可持续发展，为构建“基于尊重、公平、对等…"
