    "description": "问：据报道，巴拿马10日发生7.6级地震，已发生100余次余震。中方对此有何评论？ 答：中方向巴拿马政府和灾区人民致以慰问。截至目前，暂无中国公民在地震中伤亡报告。中国外交部和驻巴拿马使馆将继续密切关注相关情况，及时向有需要的中国公民提供必要协助。我们提醒在巴中国公民注意防范地震次生灾害。",
    "content": "问：据报道，巴拿马10日发生7.6级地震，已发生100余次余震。中方对此有何评论？ 答：中方向巴拿马政府和灾区人民致以慰问。截至目前，暂无中国公民在地震中伤亡报告。中国外交部和驻巴拿马使馆将继续密切关注相关情况，及时向有需要的中国公民提供必要协助。我们提醒在巴中国公民注意防范地震次生灾害。"
