    "description": "新华社吉隆坡10月10日电 2026年U18女篮亚洲杯10日在马来西亚芙蓉落幕。李沅珊和孙晗昀合力贡献67分，帮助中国队以106:69大胜韩国队，获得季军。 10月10日，中国队在获得季军后合影。图片来自国际篮联官网 李沅珊首节得到14分，中国队在本节结束时以30:23领先。韩国队在第二节一度将分差缩小到3分，此后中国队连得9分再度拉开比分，以51:43领先进入中场休息。 第三节开始后，中国队打出一波10:0的得分高潮，此后不断扩大优势…",
    "content": "新华社吉隆坡10月10日电 2026年U18女篮亚洲杯10日在马来西亚芙蓉落幕。李沅珊和孙晗昀合力贡献67分，帮助中国队以106:69大胜韩国队，获得季军。 10月10日，中国队在获得季军后合影。图片来自国际篮联官网 李沅珊首节得到14分，中国队在本节结束时以30:23领先。韩国队在第二节一度将分差缩小到3分，此后中国队连得9分再度拉开比分，以51:43领先进入中场休息。 第三节开始后，中国队打出一波10:0的得分高潮，此后不断扩大优势，最终收获一场37分大胜。 李沅珊得到全场最高的35分，并送出10次助攻。孙晗昀…"
