    "content": "新华社太原10月10日电 中共中央政治局委员、中央外办主任王毅10日在大同与法国总统外事顾问博纳举行第二十八次中法战略对话。 王毅说，中法战略对话服务了元首外交，巩固了政治互信。中方愿同法方一道落实好两国元首达成的共识，为中法、中欧关系行稳致远，为促进世界的和平、稳定和发展作出新的努力。 王毅表示，中方愿同法方保持高层交往，继续做大做强航空航天、核能等传统领域合作，拓展先进制造、绿色低碳、人工智能等新兴领域合作。希望法方为中国企业赴法投资兴业提供政策支持和良好环境。中法要加强沟通协调，共同推动落实习近平主席提出的四…"
