    "content": "10月2日，在乌干达坎帕拉一家石油技能培训中心，一名中国专家指导当地学员进行实操训练。新华社发（阿佳拉·纳瓦达摄） 新华社坎帕拉10月10日电（记者聂祖国）为期一个月的E-Light“铸才”·非洲青年石油技能大赛东非原油管道项目分赛10日在乌干达首都坎帕拉落幕。该活动由中国石油非洲公司主办、中国石油管道局工程有限公司（以下称中国石油管道局）组织实施，分为无损检测和职业健康安全管理两个专项，20名当地青年员工经过系统培训后参赛。 这些青年是中国石油管道局自2023年参与乌干达东非原油外输管道项目建设以来培训的技术人才…"
