    "description": "新华社北京10月10日电 题：习近平总书记同卫生健康工作者的故事 新华社记者 “不断为增进人民健康作出新贡献，为健康中国建设谱写新篇章，努力开创我国卫生健康事业新局面。” 中国医师节，是属于千万医务工作者的荣光时刻。自2018年正式设立以来，这个行业性专属节日承载着党和国家对卫生健康工作者的礼遇关怀，更饱含着习近平总书记对卫生健康工作者的殷殷期盼，对人民安康的深深牵挂。 一幕幕温暖瞬间、一次次亲切交流，见证着习近平总书记同卫生健康工作者…",
    "content": "新华社北京10月10日电 题：习近平总书记同卫生健康工作者的故事 新华社记者 “不断为增进人民健康作出新贡献，为健康中国建设谱写新篇章，努力开创我国卫生健康事业新局面。” 中国医师节，是属于千万医务工作者的荣光时刻。自2018年正式设立以来，这个行业性专属节日承载着党和国家对卫生健康工作者的礼遇关怀，更饱含着习近平总书记对卫生健康工作者的殷殷期盼，对人民安康的深深牵挂。 一幕幕温暖瞬间、一次次亲切交流，见证着习近平总书记同卫生健康工作者的深厚情谊，彰显着“人民至上、生命至上”的崇高理念。 “全心全意为人民健康服务”…"
