    "author": "罗晨,王海洲",
    "description": "新华社利雅得10月10日电（记者罗晨 王海洲）据沙特阿拉伯目击者10日称，该国首都利雅得哈立德国王国际机场3号航站楼当天下午传出爆炸声，机场内人员被疏散撤离。 沙特官方尚未对该事件发表声明，也暂无伤亡情况报告。 截止发稿时，据航班追踪网站“飞行雷达24”信息显示，该机场已无航班起降，部分飞往利雅得的航班已备降或返航。哈立德国王国际机场已发布旅客提醒说，建议旅客在前往该机场前联系航空公司并确认航班状态。 沙特阿拉伯民航总局9日发表声明说，…",
    "content": "新华社利雅得10月10日电（记者罗晨 王海洲）据沙特阿拉伯目击者10日称，该国首都利雅得哈立德国王国际机场3号航站楼当天下午传出爆炸声，机场内人员被疏散撤离。 沙特官方尚未对该事件发表声明，也暂无伤亡情况报告。 截止发稿时，据航班追踪网站“飞行雷达24”信息显示，该机场已无航班起降，部分飞往利雅得的航班已备降或返航。哈立德国王国际机场已发布旅客提醒说，建议旅客在前往该机场前联系航空公司并确认航班状态。 沙特阿拉伯民航总局9日发表声明说，位于首都利雅得的哈立德国王国际机场8日遭到两次袭击，造成3名沙特公民死亡、多人受…"
