    "author": "",
    "description": "中新网北京10月10日电 (记者 徐婧)经北京市人民政府批准，《北京市“十五五”时期知识产权发展规划》(简称《规划》)近日正式印发。《规划》明确，到2030年，北京打造知识产权支撑新质生产力创新发展集聚源、知识产权赋能重点产业强链增效引领区、知识产权纠纷高效解决优选地、知识产权高端服务资源枢纽港、知识产权国际合作交往展示窗。",
    "content": "中新网北京10月10日电 (记者 徐婧)经北京市人民政府批准，《北京市“十五五”时期知识产权发展规划》(简称《规划》)近日正式印发。《规划》明确，到2030年，北京打造知识产权支撑新质生产力创新发展集聚源、知识产权赋能重点产业强链增效引领区、知识产权纠纷高效解决优选地、知识产权高端服务资源枢纽港、知识产权国际合作交往展示窗。"
