    "title": "巴勒斯坦推迟立法委员会和总统选举",
    "link": "http://www.news.cn/20261010/9d527b6387764005aaa8e8bdf900303e/c.html",
    "pub_date": "2026-10-10 21:56:49",
    "author": "赵伟宏",
    "description": "新华社拉姆安拉10月10日电（记者赵伟宏）巴勒斯坦总统阿巴斯10日发布总统令，宣布将总统选举和立法委员会选举推迟至2027年9月11日同时举行。 此前，根据阿巴斯今年7月发布的总统令，立法委员会选举原定于今年11月28日举行，总统选举将于2027年一季度举行。 据巴勒斯坦通讯社10日报道，巴勒斯坦解放组织（巴解组织）执行委员会通过相关决议，废除了7月的总统令。报道指出，总统令基于巴勒斯坦各派别及政治力量在全国性磋商中达成的共识。 共识认…",
    "content": "新华社拉姆安拉10月10日电（记者赵伟宏）巴勒斯坦总统阿巴斯10日发布总统令，宣布将总统选举和立法委员会选举推迟至2027年9月11日同时举行。 此前，根据阿巴斯今年7月发布的总统令，立法委员会选举原定于今年11月28日举行，总统选举将于2027年一季度举行。 据巴勒斯坦通讯社10日报道，巴勒斯坦解放组织（巴解组织）执行委员会通过相关决议，废除了7月的总统令。报道指出，总统令基于巴勒斯坦各派别及政治力量在全国性磋商中达成的共识。 共识认为，以色列持续发动袭击、不断扩张定居点等措施，给按原定时间举行选举造成障碍。此外…"
