    "content": "新华社青岛10月10日电（记者李傲秋、张武岳）世界赛艇联合会顶级赛事——2026世界海岸赛艇锦标赛10日在青岛西海岸新区金沙滩开幕。这是该赛事首次在中国举办。 图为赛事开幕式现场 海岸赛艇起源于传统赛艇运动，是一项在海洋、湖泊等开放水域开展的赛艇运动。相比传统赛艇，海岸赛艇更强调运动员驾驭复杂水域环境的能力，融合速度、力量、技巧与智慧，具有较强的竞技性和观赏性。 本届赛事的竞赛日为11日至13日，设男子、女子、混合三个组别，涵盖单人艇、双人艇等7个项目，吸引了来自18个国家和地区的194名运动员参加。 赛事以“海岸…"
