    "author": "王海洲,罗晨,法赫德·阿拉伊希",
    "description": "位于沙特首都利雅得的哈立德国王国际机场8日遭到也门胡塞武装两次袭击，造成3名沙特公民死亡、多人受伤。 分析人士认为，双方持续加大军事行动力度，局势缓和仍面临重重困难。各方能否在军事对抗中控制升级风险、保留政治沟通空间，将成为影响下一步局势走向的关键。如果袭击与报复的循环持续，平民和民用设施将面临更大威胁。 记者：王海洲 罗晨 报道员：法赫德·阿拉伊希 新华社音视频部制作",
    "content": "位于沙特首都利雅得的哈立德国王国际机场8日遭到也门胡塞武装两次袭击，造成3名沙特公民死亡、多人受伤。 分析人士认为，双方持续加大军事行动力度，局势缓和仍面临重重困难。各方能否在军事对抗中控制升级风险、保留政治沟通空间，将成为影响下一步局势走向的关键。如果袭击与报复的循环持续，平民和民用设施将面临更大威胁。 记者：王海洲 罗晨 报道员：法赫德·阿拉伊希 新华社音视频部制作"
