    "description": "10月10日，由中国侨联主办、中国华侨华人研究所承办的“根魂梦：纪念中国侨联成立70周年专题学术研讨会”在北京举行。 研讨会现场。新华社记者 金良快 摄 作为纪念中国侨联成立70周年系列活动的首场活动，本次研讨会主题是“共同的根，共同的魂，共同的梦”，设立华侨华人在中国式现代化建设中的使命、百年变局视域下区域国别侨情新变化、华侨华人与推动构建人类命运共同体、新时代侨联与侨务工作发展四个分论坛。（记者范思翔）",
