    "author": "王奕涵",
    "description": "新华社华沙10月10日电（记者王奕涵）据波兰媒体10日报道，波兰首都华沙一所学校当天发生持刀袭击事件，造成3人受伤。这是波兰近日来发生的第三起校园持刀袭击事件。 据波兰TVN24新闻频道报道，袭击者为该校一名21岁学生。3名伤者中有2人受轻伤，另1人已被送往医院，暂无生命危险。袭击者已被警方逮捕。 7日上午，波兰中部马佐夫舍省奥斯特罗文卡市一所学校发生持刀袭击事件，一名19岁学生持刀伤人，造成9人受伤。8日，一名15岁少年进入马佐夫舍省…",
    "content": "新华社华沙10月10日电（记者王奕涵）据波兰媒体10日报道，波兰首都华沙一所学校当天发生持刀袭击事件，造成3人受伤。这是波兰近日来发生的第三起校园持刀袭击事件。 据波兰TVN24新闻频道报道，袭击者为该校一名21岁学生。3名伤者中有2人受轻伤，另1人已被送往医院，暂无生命危险。袭击者已被警方逮捕。 7日上午，波兰中部马佐夫舍省奥斯特罗文卡市一所学校发生持刀袭击事件，一名19岁学生持刀伤人，造成9人受伤。8日，一名15岁少年进入马佐夫舍省维什库夫市附近一所学校后，持刀袭击该校校长、一名清洁工和一名教师，致清洁工死亡。"
