    "description": "中新网拉萨10月10日电 (李林)高原初秋，阳光和煦。在拉萨，一场关乎群众切身利益的集中整治行动正悄然改变着民生服务的质感与温度。今年以来，拉萨市纪委监委立足“监督的再监督”职责定位，聚焦制度建设、数字赋能、协同共治、为民服务四大关键环节，推动民政部门扎实推进养老服务和社会救助领域突出问题专项整治，切实管好群众的“养老钱”和“救助款”，让惠民政策真正转化为百姓手中的实惠、心中的暖意。",
